fn deal_from_both_ends(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    // Unlink every node into a Vec, where both ends are one index away.
    let mut nodes = Vec::new();
    let mut cur = head;
    while let Some(mut node) = cur {
        cur = node.next.take();
        nodes.push(node);
    }
    // Deal order, as indices: 0, n-1, 1, n-2, ...
    let (mut lo, mut hi) = (0, nodes.len());
    let mut order = Vec::with_capacity(nodes.len());
    while lo < hi {
        order.push(lo);
        lo += 1;
        if lo < hi {
            hi -= 1;
            order.push(hi);
        }
    }
    // Relink back to front, so each node is attached to a finished tail.
    let mut slots: Vec<Option<Box<ListNode>>> = nodes.into_iter().map(Some).collect();
    let mut out = None;
    for &i in order.iter().rev() {
        let mut node = slots[i].take().unwrap();
        node.next = out;
        out = Some(node);
    }
    out
}

