class ListNode:
    def __init__(self, val: int = 0, next: "ListNode | None" = None):
        self.val = val
        self.next = next


def deal_from_both_ends(head: ListNode | None) -> ListNode | None:
    if head is None:
        return None
    # 1. Find the end of the front half: slow stops on node ceil(n/2).
    slow, fast = head, head.next
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    # 2. Cut there and reverse the back half, so its first node is the bottom card.
    back, slow.next = slow.next, None
    prev = None
    while back:
        back.next, prev, back = prev, back, back.next
    # 3. Interleave: front, back, front, back... The front half is never shorter.
    front, back = head, prev
    while back:
        front_next, back_next = front.next, back.next
        front.next, back.next = back, front_next
        front, back = front_next, back_next
    return head

code.rust:
fn deal_from_both_ends(mut head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    // 1. Count, then cut after the first ceil(n/2) nodes. (Box lists can't share a
    //    node between a slow and a fast pointer, so count instead.)
    let mut n = 0;
    let mut cur = head.as_ref();
    while let Some(node) = cur {
        n += 1;
        cur = node.next.as_ref();
    }
    let mut back = None;
    let mut cut = head.as_mut();
    for _ in 1..(n + 1) / 2 {
        cut = cut.and_then(|node| node.next.as_mut());
    }
    if let Some(node) = cut {
        back = node.next.take();
    }
    // 2. Reverse the back half, so its first node is the bottom card.
    let mut rev = None;
    while let Some(mut node) = back {
        back = node.next.take();
        node.next = rev;
        rev = Some(node);
    }
    // 3. Interleave, appending through a cursor to the output's last `next`.
    let (mut front, mut back) = (head, rev);
    let mut out = None;
    let mut tail = &mut out;
    while let Some(mut f) = front {
        front = f.next.take();
        tail = &mut tail.insert(f).next;
        if let Some(mut b) = back {
            back = b.next.take();
            tail = &mut tail.insert(b).next;
        }
    }
    out
}
